INSERT INTO `program_studi` (`id_prodi`, `kode_prodi`, `nama_prodi`, `jenjang`, `deskripsi`, `created_at`, `updated_at`) VALUES
(1, 'DIII-ST', 'Diploma III Statistika', 'D-III', 'Program studi Diploma III (D-III) yang fokus mempelajari keterampilan teknis dan operasional perstatistikan untuk mendukung kegiatan pengumpulan, pengolahan, penyajian, dan penyebarluasan data statistik lapangan.<br></br>\r\nInfo selengkapnya: <a href=\"https://www.stis.ac.id/hal/32/program-studi-dii-statistika\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-blue-500 hover:underline\">d3.stis.ac.id</a>', '2026-09-24 05:49:46', '2026-09-25 06:52:17'),
(2, 'DIV-ST', 'Sarjana Terapan Statistika', 'D-IV', 'Program studi Diploma IV (D-IV) yang fokus mempelajari konsep teori statistika dan metodologi analisis data untuk mendukung pengumpulan, pengolahan, serta penyajian data statistik resmi. <br></br>\r\nInfo selengkapnya: <a href=\"https://www.stis.ac.id/hal/31/program-studi-div-statistika\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-blue-500 hover:underline\">st.stis.ac.id</a>', '2026-09-24 05:49:46', '2026-09-25 06:52:32'),
(3, 'DIV-KS', 'Sarjana Terapan Komputasi Statistik', 'D-IV', 'Program studi Diploma IV (D-IV) yang berfokus pada ilmu komputer dan pemrograman untuk mendukung pengelolaan data dan sistem informasi statistik. <br></br>\r\nInfo selengkapnya: <a href=\"https://www.stis.ac.id/hal/32/program-studi-div-komputasi-statistik\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"text-blue-500 hover:underline\">ks.stis.ac.id</a>', '2026-09-24 05:49:46', '2026-09-25 06:53:24');
